sparql:
PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?item a pv:Supplier ;
        pv:country "France" .
}
GROUP BY ?value
ORDER BY DESC(?maxValue)
LIMIT 1000

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?department a pv:Department ;
             pv:hasManager ?manager .
  ?manager a pv:Manager ;
           pv:areaOfExpertise pv:Transducer .
}
GROUP BY ?department
ORDER BY ?department
LIMIT 1000

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?department a pv:Department ;
             pv:hasManager ?manager .
  ?manager a pv:Manager ;
           pv:areaOfExpertise pv:SensorsOrTransducers .
}
GROUP BY ?department
ORDER BY ASC(?department)
LIMIT 100

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?depth_mm) AS ?maxDepth)
WHERE {
  ?item a pv:BomPart ;
        pv:width_mm "15" ;
        pv:height_mm "15" ;
        pv:depth_mm ?depth_mm .
}
GROUP BY ?depth_mm
ORDER BY DESC(?depth_mm)
LIMIT 10

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?volume) AS ?maxVolume)
WHERE {
  ?item a pv:BomPart ;
        pv:width_mm ?width ;
        pv:height_mm ?height ;
        pv:depth_mm ?depth .
  BIND( ( ?width * ?height * ?depth ) AS ?volume )
}
GROUP BY ?volume
ORDER BY ASC(?volume)
LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?supplier a pv:Supplier ;
           pv:country "United States" ;
           pv:addressLocality ?value .
}
GROUP BY ?value
ORDER BY ?maxValue
LIMIT 1000

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?city (MAX(?value) AS ?maxValue)
WHERE {
  ?supplier a pv:Supplier ;
           pv:country "United States" ;
           pv:addressCountry "US" .
  ?supplier pv:addressLocality ?city .
  ?value ?predicate ?city .
}
GROUP BY ?city
ORDER BY ?city
LIMIT 100

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?department (MAX(?value) AS ?maxValue)
WHERE {
  ?department a pv:Department ;
              pv:hasDirectReport ?employee .
}
GROUP BY ?department
HAVING (COUNT(?employee) > 5)
ORDER BY DESC(COUNT(?employee))
LIMIT 10

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?department a pv:Department .
  OPTIONAL { ?department pv:hasManager ?manager }
  FILTER (NOT EXISTS { ?department pv:hasManager ?manager })
}
GROUP BY ?department
ORDER BY ?department
LIMIT 1000

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?supplier a pv:Supplier ;
           pv:name ?name ;
           pv:addressText ?addressText ;
           pv:addressLocality ?addressLocality ;
           pv:addressCountryCode ?addressCountryCode ;
           pv:addressCountry ?addressCountry .
}
GROUP BY ?name
ORDER BY ?name
LIMIT 1000

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?price2) AS ?maxPrice) WHERE {
  ?product a pv:Product ;
           pv:compatibleProduct ?compatibleProduct .
  ?product pv:price ?price1 .
  ?compatibleProduct pv:price ?price2 .
}
GROUP BY ?price2
ORDER BY DESC(?price2)
LIMIT 100

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?itemID (MAX(?value) AS ?maxValue)
WHERE {
  ?item a pv:Hardware ;
        pv:name ?value ;
        pv:id ?itemID .
  OPTIONAL {
    ?item pv:hasProductManager ?manager .
  }
  FILTER NOT EXISTS {
    ?item pv:hasProductManager ?manager .
  }
}
GROUP BY ?itemID
ORDER BY ?itemID
LIMIT 1000

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (MAX(?value) AS ?maxValue)
WHERE {
  ?item a pv:Supplier ;
        pv:reliabilityIndex ?value .
}
GROUP BY ?value
ORDER BY DESC(?maxValue)
LIMIT 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX ecc: <https://ns.eccenca.com/>
SELECT ?bom ?bomPart ?supplier ?country
WHERE {
  ?bom a pv:BillOfMaterial ;
       pv:hasBomPart ?bomPart .
  ?bomPart a pv:BomPart ;
           pv:hasSupplier ?supplier .
  ?supplier pv:country ecc:Poland .
}
GROUP BY ?bom ?bomPart ?supplier ?country
ORDER BY ?bom
LIMIT 1000
